// Daily dependency updates. See docs/development-checks.md#dependency-updates.
//
// `prepare` runs without repository write credentials: it tries updates, runs
// the CI checks, and writes proposals. `publish` turns those proposals into
// pull requests with the automation App token and never runs package code.
import { spawn } from "node:child_process";
import { cp, mkdir, mkdtemp, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const PI_PACKAGES = ["@earendil-works/pi-agent-core", "@earendil-works/pi-ai", "@earendil-works/pi-coding-agent"];
export const PI_KEY = "@earendil-works/pi-coding-agent";
const DEPENDENCY_FIELDS = ["dependencies", "optionalDependencies", "devDependencies"];
const RUNTIME_FIELDS = new Set(["dependencies", "optionalDependencies"]);
const PACKAGE_NAME = "@jmfederico/pi-web";
const POLICY_FILE = "dependency-policy.json";
const AUTO_BRANCH = "automation/dependency-updates";
const MAINTAINER = "jmfederico";
const ATTRIBUTION = "*Automatically generated by the user's AI workflow.*";
// Mirrors the Linux CI jobs. Windows tests run only in pull request CI.
export const VERIFY_STEPS = [
  ["npm", "ci", "--no-audit", "--no-fund"],
  ["npm", "run", "typecheck"],
  ["npm", "run", "lint"],
  ["npm", "run", "knip"],
  ["npm", "test"],
  ["npm", "run", "build"],
  ["npm", "run", "check:artifacts"],
  ["npx", "playwright", "install", "--with-deps", "chromium", "firefox", "webkit"],
  ["npm", "run", "test:browser"],
];

// ---------------------------------------------------------------- versions

export function parseVersion(value) {
  const match = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/u.exec(value ?? "");
  if (match === null) return undefined;
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]), prerelease: match[4] };
}

export function compareVersions(a, b) {
  const left = parseVersion(a);
  const right = parseVersion(b);
  if (left === undefined || right === undefined) throw new Error(`Cannot compare versions ${a} and ${b}`);
  for (const key of ["major", "minor", "patch"]) {
    if (left[key] !== right[key]) return left[key] - right[key];
  }
  if (left.prerelease === right.prerelease) return 0;
  if (left.prerelease === undefined) return 1;
  if (right.prerelease === undefined) return -1;
  return left.prerelease < right.prerelease ? -1 : 1;
}

/** Supports the spec forms this repository uses: exact, ^, ~ and npm aliases of those. */
export function parseSpec(spec) {
  const alias = /^npm:((?:@[^/@]+\/)?[^@]+)@(.+)$/u.exec(spec);
  const range = alias === null ? spec : alias[2];
  const match = /^([\^~]?)(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)$/u.exec(range);
  if (match === null) return undefined;
  return { alias: alias?.[1], operator: match[1], version: match[2] };
}

export function formatSpec(parsed, version, operator = parsed.operator) {
  const range = `${operator}${version}`;
  return parsed.alias === undefined ? range : `npm:${parsed.alias}@${range}`;
}

export function satisfies(version, spec) {
  const parsed = parseSpec(spec);
  const candidate = parseVersion(version);
  const floor = parsed === undefined ? undefined : parseVersion(parsed.version);
  if (parsed === undefined || candidate === undefined || floor === undefined) return false;
  if (compareVersions(version, parsed.version) < 0) return false;
  if (parsed.operator === "") return compareVersions(version, parsed.version) === 0;
  if (candidate.prerelease !== undefined) return false;
  if (parsed.operator === "~") return candidate.major === floor.major && candidate.minor === floor.minor;
  if (floor.major > 0) return candidate.major === floor.major;
  if (floor.minor > 0) return candidate.major === 0 && candidate.minor === floor.minor;
  return compareVersions(version, parsed.version) === 0;
}

/** PI WEB supports the latest Pi minor line; a higher patch floor in that line is deliberate. */
export function piSpec(currentSpec, target) {
  const current = parseSpec(currentSpec);
  const next = parseVersion(target);
  const floor = current === undefined ? undefined : parseVersion(current.version);
  if (next === undefined) throw new Error(`Invalid Pi version ${target}`);
  if (floor !== undefined && floor.major === next.major && floor.minor === next.minor) return currentSpec;
  return `^${next.major}.${next.minor}.0`;
}

// ---------------------------------------------------------------- planning

export function directDependencies(manifest) {
  return DEPENDENCY_FIELDS.flatMap((field) =>
    Object.entries(manifest[field] ?? {}).map(([name, spec]) => ({ name, field, spec })));
}

export function lockedVersion(lock, name) {
  return lock.packages?.[`node_modules/${name}`]?.version;
}

/** The registry package behind a dependency name, following npm aliases. */
export function registryName(dependency) {
  return parseSpec(dependency.spec)?.alias ?? dependency.name;
}

function heldBack(hold, target) {
  return hold !== undefined && (hold.version === "*" || compareVersions(target, hold.version) <= 0);
}

/**
 * Builds update units: one per non-Pi dependency, and one for Pi with the
 * packages that follow it. `latest` maps dependency names to registry versions.
 */
export function planUnits({ manifest, lock, latest, policy, piDependencies = {} }) {
  const follow = policy.follow ?? {};
  const holds = policy.holds ?? {};
  const units = [];
  const skipped = [];
  for (const dependency of directDependencies(manifest)) {
    const { name, field, spec } = dependency;
    if (PI_PACKAGES.includes(name) || follow[name] !== undefined) continue;
    const parsed = parseSpec(spec);
    const from = lockedVersion(lock, name);
    const target = latest[name];
    if (parsed === undefined || from === undefined || parseVersion(target) === undefined) {
      skipped.push({ name, reason: `unsupported version spec or no registry version (${spec})` });
      continue;
    }
    if (compareVersions(target, from) <= 0) continue;
    if (heldBack(holds[name], target)) {
      skipped.push({ name, version: target, reason: holds[name].reason });
      continue;
    }
    const toSpec = satisfies(target, spec) ? spec : formatSpec(parsed, target);
    units.push({ id: name, kind: "package", changes: [{ name, field, fromSpec: spec, toSpec, fromVersion: from, toVersion: target }] });
  }
  const pi = planPiUnit({ manifest, lock, latest, holds, follow, piDependencies });
  if (pi.skipped !== undefined) skipped.push(pi.skipped);
  return { units, skipped, pi: pi.unit };
}

function planPiUnit({ manifest, lock, latest, holds, follow, piDependencies }) {
  const from = lockedVersion(lock, PI_KEY);
  const target = latest[PI_KEY];
  if (from === undefined || parseVersion(target) === undefined || compareVersions(target, from) <= 0) return {};
  if (heldBack(holds[PI_KEY], target)) return { skipped: { name: "Pi", version: target, reason: holds[PI_KEY].reason } };
  const dependencies = directDependencies(manifest);
  const changes = dependencies.filter(({ name }) => PI_PACKAGES.includes(name)).map(({ name, field, spec }) => {
    const toVersion = latest[name] ?? target;
    return { name, field, fromSpec: spec, toSpec: piSpec(spec, toVersion), fromVersion: lockedVersion(lock, name), toVersion };
  });
  for (const [name, rule] of Object.entries(follow)) {
    const dependency = dependencies.find((entry) => entry.name === name);
    const pinned = piDependencies[name];
    if (rule.dependencyOf !== PI_KEY || dependency === undefined || parseVersion(pinned) === undefined) continue;
    const parsed = parseSpec(dependency.spec);
    if (parsed === undefined || lockedVersion(lock, name) === pinned) continue;
    changes.push({
      name, field: dependency.field, fromSpec: dependency.spec, toSpec: formatSpec(parsed, pinned, ""),
      fromVersion: lockedVersion(lock, name), toVersion: pinned, follows: PI_KEY,
    });
  }
  const major = parseVersion(target).major > parseVersion(from).major;
  return { unit: { id: "pi", kind: "pi", major, fromVersion: from, toVersion: target, changes } };
}

/** The manifest npm resolves from: every direct dependency pinned to its kept or accepted version. */
export function frozenManifest(manifest, lock, accepted) {
  const targets = new Map(accepted.flatMap((unit) => unit.changes ?? []).map((change) => [change.name, change.toVersion]));
  const result = structuredClone(manifest);
  for (const { name, field, spec } of directDependencies(manifest)) {
    const parsed = parseSpec(spec);
    const version = targets.get(name) ?? lockedVersion(lock, name);
    if (parsed !== undefined && version !== undefined) result[field][name] = formatSpec(parsed, version, "");
  }
  return result;
}

/** Edits only the changed specs, so package.json keeps its formatting. */
export function rewriteSpecs(text, accepted) {
  let result = text;
  for (const change of accepted.flatMap((unit) => unit.changes ?? [])) {
    if (change.toSpec === change.fromSpec) continue;
    const needle = `${JSON.stringify(change.name)}: ${JSON.stringify(change.fromSpec)}`;
    const count = result.split(needle).length - 1;
    if (count !== 1) throw new Error(`Expected one ${needle} in package.json, found ${String(count)}`);
    result = result.replace(needle, () => `${JSON.stringify(change.name)}: ${JSON.stringify(change.toSpec)}`);
  }
  return result;
}

/**
 * Finds the largest passing subset by bisection. A single failing unit is
 * retried once so one flaky run does not hold a version back.
 */
export async function selectPassing(candidates, attempt, accepted = []) {
  if (candidates.length === 0) return { accepted, rejected: [] };
  const result = await attempt([...accepted, ...candidates]);
  if (result.ok) return { accepted: [...accepted, ...candidates], rejected: [] };
  if (candidates.length === 1) {
    if (result.deterministic === true) return { accepted, rejected: [{ unit: candidates[0], result }] };
    const retry = await attempt([...accepted, ...candidates]);
    return retry.ok ? { accepted: [...accepted, ...candidates], rejected: [] } : { accepted, rejected: [{ unit: candidates[0], result }] };
  }
  const middle = Math.ceil(candidates.length / 2);
  const left = await selectPassing(candidates.slice(0, middle), attempt, accepted);
  const right = await selectPassing(candidates.slice(middle), attempt, left.accepted);
  return { accepted: right.accepted, rejected: [...left.rejected, ...right.rejected] };
}

/** Records why versions are held back, and forgets holds that no longer apply. */
export function updateHolds(policy, { accepted, rejected, manifest, lock, today }) {
  const holds = { ...policy.holds };
  for (const unit of accepted) {
    if (unit.kind === "package") delete holds[unit.id];
    if (unit.kind === "pi") delete holds[PI_KEY];
  }
  for (const { unit, result } of rejected) {
    if (unit.kind !== "package") continue;
    const change = unit.changes[0];
    holds[unit.id] = {
      ...(holds[unit.id]?.note === undefined ? {} : { note: holds[unit.id].note }),
      version: change.toVersion,
      reason: `\`${result.step}\` failed with ${change.name} ${change.toVersion}.`,
      details: result.excerpt.slice(-1000),
      recorded: today,
    };
  }
  const names = new Set(directDependencies(manifest).map(({ name }) => name));
  for (const [name, hold] of Object.entries(holds)) {
    if (!names.has(name)) {
      delete holds[name];
      continue;
    }
    const current = lockedVersion(lock, name);
    if (hold.version !== "*" && current !== undefined && parseVersion(hold.version) !== undefined
      && compareVersions(current, hold.version) >= 0) delete holds[name];
  }
  return { ...policy, holds: Object.fromEntries(Object.entries(holds).sort(([a], [b]) => a.localeCompare(b))) };
}

export function changesetText(accepted) {
  const changes = accepted.flatMap((unit) => unit.changes ?? []);
  const runtime = changes.filter((change) => RUNTIME_FIELDS.has(change.field) && change.toSpec !== change.fromSpec);
  const pi = changes.find((change) => change.name === PI_KEY && change.toSpec !== change.fromSpec);
  const lines = [];
  if (runtime.length > 0) {
    lines.push(`Update runtime dependencies: ${runtime.map((change) => `${change.name} ${change.toSpec}`).join(", ")}.`);
  }
  if (pi !== undefined) lines.push(`Support Pi ${pi.toSpec.replace(/^\^/u, "")} or later.`);
  if (lines.length === 0) return undefined;
  return `---\n"${PACKAGE_NAME}": patch\n---\n\n${lines.join(" ")}\n`;
}

/** Extracts "Breaking Changes" entries for versions after `from` up to `to` from a Pi changelog. */
export function breakingChanges(changelog, from, to) {
  const entries = [];
  let version;
  let inBreaking = false;
  for (const line of changelog.split(/\r?\n/u)) {
    const heading = /^## \[([^\]]+)\]/u.exec(line);
    if (heading !== null) {
      version = parseVersion(heading[1]) === undefined ? undefined : heading[1];
      inBreaking = false;
      continue;
    }
    if (/^### /u.test(line)) {
      inBreaking = /^### Breaking Changes/u.test(line);
      continue;
    }
    if (!inBreaking || version === undefined || !line.startsWith("- ")) continue;
    if (compareVersions(version, from) > 0 && compareVersions(version, to) <= 0) entries.push({ version, text: line.slice(2) });
  }
  return entries;
}

function changeLine(change) {
  const spec = change.toSpec === change.fromSpec ? "" : ` (\`${change.fromSpec}\` → \`${change.toSpec}\`)`;
  return `- \`${change.name}\` ${change.fromVersion} → ${change.toVersion}${spec}`;
}

function excerptBlock(text) {
  return `\`\`\`text\n${text.replaceAll("```", "``\u200b`").trim()}\n\`\`\``;
}

export function autoPullRequest({ accepted, rejected, skipped, refreshed }) {
  const changes = accepted.flatMap((unit) => unit.changes ?? []);
  const piChange = changes.find((change) => change.name === PI_KEY && change.toSpec !== change.fromSpec);
  const lines = ["## What and why", ""];
  lines.push(changes.length > 0 || refreshed > 0
    ? "Daily dependency update. These versions passed typecheck, lint, knip, the Linux tests, the build and artifact checks, and the browser tests:"
    : "Daily dependency update. No newer versions passed the checks; this records why they are held back.");
  if (changes.length > 0 || refreshed > 0) lines.push("");
  lines.push(...changes.map(changeLine));
  if (refreshed > 0) lines.push(`- ${String(refreshed)} indirect packages updated within their declared ranges.`);
  if (piChange !== undefined) {
    lines.push("", `PI WEB will support Pi ${piChange.toSpec.replace(/^\^/u, "")} or later, following the latest Pi minor line.`);
  }
  if (rejected.length > 0 || skipped.length > 0) {
    lines.push("", `Held back (recorded in \`${POLICY_FILE}\`):`);
    lines.push(...rejected.map(({ unit, result }) => unit.kind === "refresh"
      ? `- Indirect package updates: \`${result.step}\` failed, so the lockfile keeps them as they are.`
      : `- \`${unit.id}\` ${unit.changes?.[0]?.toVersion ?? ""}: \`${result.step}\` failed.`));
    lines.push(...skipped.map((entry) => `- \`${entry.name}\`${entry.version === undefined ? "" : ` ${entry.version}`}: ${entry.reason}`));
  }
  if (rejected.length > 0) {
    lines.push("", "<details>", "<summary>Additional information</summary>", "");
    for (const { unit, result } of rejected) lines.push(`${unit.id}, \`${result.step}\`:`, "", excerptBlock(result.excerpt), "");
    lines.push("</details>");
  }
  lines.push("", ATTRIBUTION, "");
  return { branch: AUTO_BRANCH, title: "chore(deps): update dependencies", body: lines.join("\n"), labels: [], assignees: [] };
}

export function piPullRequest({ unit, result, breaking }) {
  const why = unit.major
    ? `it is a new major version${result?.ok === false ? `, and \`${result.step}\` failed with it` : result?.ok === true ? "; the checks passed with it" : ""}`
    : `\`${result.step}\` failed with it`;
  const lines = [
    "## What and why",
    "",
    `Pi ${unit.toVersion} is available; PI WEB uses ${unit.fromVersion}. It needs a decision before PI WEB adopts it because ${why}.`,
    "",
    `To adopt it, fix PI WEB on this branch and remove the \`do-not-merge\` label. To stay on ${unit.fromVersion}, add a hold for \`${PI_KEY}\` with version \`${unit.toVersion}\` and the reason to \`${POLICY_FILE}\`, then close this PR.`,
    "",
    `@${MAINTAINER}`,
    "",
    "<details>",
    "<summary>Additional information</summary>",
    "",
    ...unit.changes.map(changeLine),
  ];
  if (result?.ok === false) lines.push("", `\`${result.step}\` output:`, "", excerptBlock(result.excerpt));
  if (breaking.length > 0) {
    lines.push("", "Breaking changes listed in Pi's changelog:", "", ...breaking.map((entry) => `- ${entry.version}: ${entry.text}`));
  }
  lines.push("", "</details>", "", ATTRIBUTION, "");
  return {
    branch: `automation/pi-${unit.toVersion}`,
    title: `chore(deps): update Pi to ${unit.toVersion} (needs decision)`,
    body: lines.join("\n"),
    labels: ["do-not-merge"],
    assignees: [MAINTAINER],
  };
}

// ---------------------------------------------------------------- process I/O

const ANSI = /\u001B\[[0-9;?]*[ -/]*[@-~]/gu;

async function run(command, args, { cwd, env, allowFailure = false, timeoutMs = 45 * 60_000, quiet = false } = {}) {
  const child = spawn(command, args, { cwd, env: { ...process.env, ...env }, stdio: ["ignore", "pipe", "pipe"] });
  let output = "";
  const collect = (chunk) => {
    const text = chunk.toString();
    if (!quiet) process.stdout.write(text);
    output = (output + text).slice(-200_000);
  };
  child.stdout.on("data", collect);
  child.stderr.on("data", collect);
  const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
  const code = await new Promise((resolve) => child.on("close", (exitCode, signal) => resolve(exitCode ?? signal)));
  clearTimeout(timer);
  if (code !== 0 && !allowFailure) throw new Error(`${command} ${args.join(" ")} failed (${String(code)}):\n${output.slice(-4000)}`);
  return { ok: code === 0, output: output.replace(ANSI, "") };
}

const NOISE = /^npm error\s*$|A complete log of this run|For a full report see|\/_logs\//u;

export function tail(text, lines = 40) {
  return text.split(/\r?\n/u).filter((line) => line.trim() !== "" && !NOISE.test(line)).slice(-lines).join("\n").slice(-6000);
}

async function readJson(path) {
  return JSON.parse(await readFile(path, "utf8"));
}

function json(value) {
  return `${JSON.stringify(value, null, 2)}\n`;
}

const NPM_LOCK_ONLY = ["--package-lock-only", "--ignore-scripts", "--no-audit", "--no-fund"];

/** Resolves a lockfile for the units. Resolution conflicts are results, not crashes. */
async function applyUnits(cwd, base, accepted) {
  const npm = async (command) => {
    const result = await run("npm", [command, ...NPM_LOCK_ONLY], { cwd, quiet: true, allowFailure: true });
    return result.ok ? undefined : { ok: false, deterministic: true, step: `npm ${command} (dependency resolution)`, excerpt: tail(result.output) };
  };
  await writeFile(join(cwd, "package-lock.json"), base.lockText);
  await writeFile(join(cwd, "package.json"), json(frozenManifest(base.manifest, base.lock, accepted)));
  const failure = await npm("install")
    ?? (accepted.some((unit) => unit.kind === "refresh") ? await npm("update") : undefined);
  if (failure !== undefined) return failure;
  const manifestText = rewriteSpecs(base.manifestText, accepted);
  await writeFile(join(cwd, "package.json"), manifestText);
  const final = await npm("install");
  if (final !== undefined) return final;
  // npm may reformat package.json; only the specs are meant to change.
  await writeFile(join(cwd, "package.json"), manifestText);
  return { ok: true, manifestText, lockText: await readFile(join(cwd, "package-lock.json"), "utf8") };
}

/** `DEPENDENCY_UPDATES_CHECKS` (a JSON array of argv arrays) replaces the checks for local trial runs. */
function verifySteps() {
  const override = process.env.DEPENDENCY_UPDATES_CHECKS;
  return override === undefined || override === "" ? VERIFY_STEPS : JSON.parse(override);
}

async function verify(cwd) {
  for (const [command, ...args] of verifySteps()) {
    const step = [command, ...args].join(" ");
    console.log(`::group::${step}`);
    const result = await run(command, args, { cwd, allowFailure: true });
    console.log("::endgroup::");
    if (!result.ok) return { ok: false, step, excerpt: tail(result.output) };
  }
  return { ok: true };
}

function lockVersions(lockText) {
  const lock = JSON.parse(lockText);
  return new Map(Object.entries(lock.packages ?? {}).filter(([key]) => key !== "").map(([key, value]) => [key, value.version]));
}

function countIndirectChanges(beforeText, afterText, accepted) {
  const direct = new Set(accepted.flatMap((unit) => unit.changes ?? []).map((change) => `node_modules/${change.name}`));
  const before = lockVersions(beforeText);
  const after = lockVersions(afterText);
  const keys = new Set([...before.keys(), ...after.keys()]);
  return [...keys].filter((key) => !direct.has(key) && before.get(key) !== after.get(key)).length;
}

async function registryVersions(names) {
  const entries = await Promise.all([...new Set(names)].map(async (name) => {
    const result = await run("npm", ["view", name, "dist-tags.latest"], { quiet: true, allowFailure: true });
    return [name, result.ok ? result.output.trim() : undefined];
  }));
  return Object.fromEntries(entries);
}

async function piChangelog(version) {
  const directory = await mkdtemp(join(tmpdir(), "pi-changelog-"));
  try {
    const packed = await run("npm", ["pack", `${PI_KEY}@${version}`, "--pack-destination", directory, "--silent"], { quiet: true });
    const tarball = join(directory, packed.output.trim().split(/\r?\n/u).at(-1));
    await run("tar", ["-xzf", tarball, "-C", directory, "package/CHANGELOG.md"], { quiet: true });
    return await readFile(join(directory, "package", "CHANGELOG.md"), "utf8");
  } catch {
    return "";
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

async function writeProposal(out, name, pullRequest, files) {
  const directory = join(out, name);
  for (const [path, content] of Object.entries(files)) {
    await mkdir(dirname(join(directory, "files", path)), { recursive: true });
    await writeFile(join(directory, "files", path), content);
  }
  await writeFile(join(directory, "pull-request.json"), json(pullRequest));
}

async function prepare({ cwd, out, today }) {
  const manifestText = await readFile(join(cwd, "package.json"), "utf8");
  const lockText = await readFile(join(cwd, "package-lock.json"), "utf8");
  const policyText = await readFile(join(cwd, POLICY_FILE), "utf8");
  const base = { manifestText, lockText, manifest: JSON.parse(manifestText), lock: JSON.parse(lockText) };
  const policy = JSON.parse(policyText);
  const dependencies = directDependencies(base.manifest);
  const registry = await registryVersions(dependencies.map(registryName));
  const latest = Object.fromEntries(dependencies.map((dependency) => [dependency.name, registry[registryName(dependency)]]));
  const piTarget = latest[PI_KEY];
  const piDependencies = piTarget === undefined ? {} : JSON.parse((await run("npm", ["view", `${PI_KEY}@${piTarget}`, "dependencies", "--json"], { quiet: true })).output || "{}");
  const plan = planUnits({ manifest: base.manifest, lock: base.lock, latest, policy, piDependencies });

  const candidates = [...plan.units];
  const refresh = { id: "refresh", kind: "refresh" };
  const refreshProbe = await applyUnits(cwd, base, [refresh]);
  if (!refreshProbe.ok || refreshProbe.lockText !== base.lockText) candidates.unshift(refresh);
  if (plan.pi !== undefined && !plan.pi.major) candidates.push(plan.pi);
  console.log(`Candidates: ${candidates.map((unit) => unit.id).join(", ") || "none"}`);

  // Proposals reuse the exact files that passed, because the registry can
  // publish newer in-range versions while this job runs.
  const passing = new Map([["", { manifestText, lockText }]]);
  const key = (units) => units.map((unit) => unit.id).sort().join("\n");
  const attempt = async (units) => {
    console.log(`::notice::Trying ${units.map((unit) => unit.id).join(", ") || "the current main branch"}`);
    const files = await applyUnits(cwd, base, units);
    if (!files.ok) return files;
    const result = await verify(cwd);
    if (result.ok) passing.set(key(units), files);
    return result;
  };
  // Units that cannot even resolve on their own are rejected without running checks.
  const unresolvable = [];
  for (const unit of candidates) {
    const files = await applyUnits(cwd, base, [unit]);
    if (!files.ok) unresolvable.push({ unit, result: files });
  }
  const resolvable = candidates.filter((unit) => !unresolvable.some((entry) => entry.unit === unit));
  const bisected = await selectPassing(resolvable, attempt);
  const selection = { accepted: bisected.accepted, rejected: [...unresolvable, ...bisected.rejected] };
  if (bisected.rejected.length > 0) {
    // A failing main branch must not be recorded as a reason to hold versions back.
    const baseline = await attempt([]);
    if (!baseline.ok) throw new Error(`The current main branch fails \`${baseline.step}\`; no proposals were made.\n${baseline.excerpt}`);
  }

  const proposals = [];
  const piRejected = selection.rejected.find(({ unit }) => unit.kind === "pi");
  const rejected = selection.rejected.filter(({ unit }) => unit.kind !== "pi");
  const skipped = [...plan.skipped];

  if (plan.pi !== undefined && (plan.pi.major || piRejected !== undefined)) {
    const piResult = piRejected?.result ?? await attempt([plan.pi]);
    const piFiles = await applyUnits(cwd, base, [plan.pi]);
    if (piFiles.ok) {
      const files = { "package.json": piFiles.manifestText, "package-lock.json": piFiles.lockText };
      const changeset = changesetText([plan.pi]);
      if (changeset !== undefined) files[`.changeset/dependency-updates-${today}-pi.md`] = changeset;
      const breaking = breakingChanges(await piChangelog(plan.pi.toVersion), plan.pi.fromVersion, plan.pi.toVersion);
      await writeProposal(out, "pi", piPullRequest({ unit: plan.pi, result: piResult, breaking }), files);
      proposals.push("pi");
    } else {
      // Without a lockfile there is no branch to propose; report it with the other updates.
      console.log(`::warning::Pi ${plan.pi.toVersion} cannot be resolved: ${piFiles.excerpt}`);
      skipped.push({ name: "Pi", version: plan.pi.toVersion, reason: `\`${piFiles.step}\` failed; see the workflow log.` });
    }
  }

  const accepted = selection.accepted;
  const result = passing.get(key(accepted));
  if (result === undefined) throw new Error("The accepted updates have no passing run");
  const nextPolicy = updateHolds(policy, { accepted, rejected, manifest: base.manifest, lock: JSON.parse(result.lockText), today });
  const nextPolicyText = json(nextPolicy);
  if (result.lockText !== base.lockText || result.manifestText !== manifestText || nextPolicyText !== policyText) {
    const files = { "package.json": result.manifestText, "package-lock.json": result.lockText };
    if (nextPolicyText !== policyText) files[POLICY_FILE] = nextPolicyText;
    const changeset = changesetText(accepted);
    if (changeset !== undefined) files[`.changeset/dependency-updates-${today}.md`] = changeset;
    const refreshed = accepted.some((unit) => unit.kind === "refresh") ? countIndirectChanges(base.lockText, result.lockText, accepted) : 0;
    await writeProposal(out, "auto", autoPullRequest({ accepted, rejected, skipped, refreshed }), files);
    proposals.push("auto");
  }

  // Leave the checkout as it was so later steps see the base manifest.
  await writeFile(join(cwd, "package.json"), manifestText);
  await writeFile(join(cwd, "package-lock.json"), lockText);
  return proposals;
}

// ---------------------------------------------------------------- publishing

const PUBLISHABLE = /^(?:package\.json|package-lock\.json|dependency-policy\.json|\.changeset\/dependency-updates-\d{4}-\d{2}-\d{2}(?:-pi)?\.md)$/u;

async function listFiles(root, prefix = "") {
  const entries = await readdir(join(root, prefix), { withFileTypes: true });
  const files = await Promise.all(entries.map((entry) => entry.isDirectory()
    ? listFiles(root, join(prefix, entry.name))
    : [join(prefix, entry.name)]));
  return files.flat();
}

async function gh(args, options) {
  return (await run("gh", args, { quiet: true, ...options })).output.trim();
}

async function publishProposal({ cwd, directory, baseSha, repository, identity }) {
  const pullRequest = await readJson(join(directory, "pull-request.json"));
  const files = await listFiles(join(directory, "files"));
  const unexpected = files.filter((path) => !PUBLISHABLE.test(path.split("\\").join("/")));
  if (unexpected.length > 0) throw new Error(`Refusing to publish unexpected files: ${unexpected.join(", ")}`);
  JSON.parse(await readFile(join(directory, "files", "package.json"), "utf8"));
  JSON.parse(await readFile(join(directory, "files", "package-lock.json"), "utf8"));

  const existing = JSON.parse(await gh(["pr", "list", "-R", repository, "--head", pullRequest.branch, "--state", "all",
    "--json", "number,state,mergeable,headRefName"]));
  const open = existing.find((entry) => entry.state === "OPEN");
  if (open !== undefined && open.mergeable !== "CONFLICTING") {
    console.log(`PR #${String(open.number)} for ${pullRequest.branch} is still open; leaving it for review.`);
    return;
  }
  if (open === undefined && existing.length > 0 && pullRequest.branch !== AUTO_BRANCH) {
    console.log(`A PR for ${pullRequest.branch} was already closed or merged; not reopening it.`);
    return;
  }

  await run("git", ["checkout", "--detach", baseSha], { cwd });
  await run("git", ["checkout", "-B", pullRequest.branch], { cwd });
  await cp(join(directory, "files"), cwd, { recursive: true });
  await run("git", ["add", "--", ...files], { cwd });
  await run("git", ["-c", `user.name=${identity.name}`, "-c", `user.email=${identity.email}`,
    "commit", "--quiet", "-m", pullRequest.title], { cwd });
  await run("git", ["push", "--force", "origin", `HEAD:refs/heads/${pullRequest.branch}`], { cwd, quiet: true });

  const bodyFile = join(directory, "body.md");
  await writeFile(bodyFile, pullRequest.body);
  if (open !== undefined) {
    await gh(["pr", "edit", String(open.number), "-R", repository, "--title", pullRequest.title, "--body-file", bodyFile]);
    console.log(`Updated PR #${String(open.number)}.`);
    return;
  }
  const url = await gh(["pr", "create", "-R", repository, "--base", "main", "--head", pullRequest.branch,
    "--title", pullRequest.title, "--body-file", bodyFile,
    ...pullRequest.labels.flatMap((label) => ["--label", label]),
    ...pullRequest.assignees.flatMap((assignee) => ["--assignee", assignee])]);
  console.log(`Opened ${url}`);
}

async function publish({ cwd, input, baseSha, repository, appSlug }) {
  const login = `${appSlug}[bot]`;
  const id = await gh(["api", `users/${login}`, "--jq", ".id"]);
  const identity = { name: login, email: `${id}+${login}@users.noreply.github.com` };
  for (const name of ["auto", "pi"]) {
    const directory = join(input, name);
    const present = await readdir(directory).then(() => true, () => false);
    if (present) await publishProposal({ cwd, directory, baseSha, repository, identity });
  }
}

// ---------------------------------------------------------------- CLI

function option(args, name) {
  const index = args.indexOf(name);
  const value = index === -1 ? undefined : args[index + 1];
  if (value === undefined) throw new Error(`Missing ${name}`);
  return value;
}

async function main(args) {
  const cwd = process.cwd();
  if (args[0] === "prepare") {
    const out = option(args, "--out");
    await mkdir(out, { recursive: true });
    const proposals = await prepare({ cwd, out, today: new Date().toISOString().slice(0, 10) });
    console.log(`Proposals: ${proposals.join(", ") || "none"}`);
    if (process.env.GITHUB_OUTPUT !== undefined) await writeFile(process.env.GITHUB_OUTPUT, `proposals=${proposals.join(",")}\n`, { flag: "a" });
    return;
  }
  if (args[0] === "publish") {
    await publish({
      cwd, input: option(args, "--in"), baseSha: option(args, "--base"),
      repository: option(args, "--repository"), appSlug: option(args, "--app-slug"),
    });
    return;
  }
  throw new Error("Usage: dependency-updates.mjs prepare --out <dir> | publish --in <dir> --base <sha> --repository <owner/name> --app-slug <slug>");
}

if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) {
  await main(process.argv.slice(2));
}
